import numpy as np

def check_internal_9(r, c, grid):
    """Check if 9 is surrounded by 3s (no 0 neighbors in 3x3)"""
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 0:
                    return False
    return True

def check_internal_9_region(r, c, grid):
    """Check if 9 is surrounded by 3s within the region only"""
    region_mask = np.array(grid) > 0  # Non-background cells
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 0:
                    return False
            # Check if this position is outside region
            if not region_mask[nr, nc]:
                return False
    return True

# Let me check each 9
print("9s and their internal status:")
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == 9:
            internal = check_internal_9(r, c, grid)
            print(f"9 at ({r},{c}): internal={internal}")

